DROP TABLE IF EXISTS "search_macro_node";

CREATE TABLE "search_macro_node" (
    id BIGINT PRIMARY KEY REFERENCES "macro_node"("id") ON UPDATE CASCADE ON DELETE CASCADE,
    "short_name" TEXT,
    "full_name" TEXT,
    "scenario_id" BIGINT
);

CREATE INDEX "search_macro_node_short_name" ON "search_macro_node" USING gin ("short_name" gin_trgm_ops);
CREATE INDEX "search_macro_node_full_name" ON "search_macro_node" USING gin ("full_name" gin_trgm_ops);
CREATE INDEX "search_macro_node_scenario_id" ON "search_macro_node" ("scenario_id");

CREATE OR REPLACE FUNCTION search_macro_node__ins_trig_fun()
    RETURNS TRIGGER
    LANGUAGE plpgsql
AS $$
BEGIN
    INSERT INTO "search_macro_node" (id, short_name, full_name, scenario_id)
        SELECT "macro_node".id AS id, osrd_prepare_for_search(macro_node.short_name) AS short_name,
    osrd_prepare_for_search(macro_node.full_name) AS full_name,
    (macro_node.scenario_id) AS scenario_id
        FROM (SELECT NEW.*) AS "macro_node"
        ;
    RETURN NEW;
END;
$$;
CREATE OR REPLACE TRIGGER search_macro_node__ins_trig
AFTER INSERT ON "macro_node"
FOR EACH ROW EXECUTE FUNCTION search_macro_node__ins_trig_fun();


CREATE OR REPLACE FUNCTION search_macro_node__upd_trig_fun()
    RETURNS TRIGGER
    LANGUAGE plpgsql
AS $$
BEGIN
    UPDATE "search_macro_node"
        SET "short_name" = osrd_prepare_for_search(macro_node.short_name),
        "full_name" = osrd_prepare_for_search(macro_node.full_name),
        "scenario_id" = (macro_node.scenario_id)
        FROM (SELECT NEW.*) AS "macro_node"
        
        WHERE "macro_node".id = "search_macro_node".id;
    RETURN NEW;
END;
$$;
CREATE OR REPLACE TRIGGER search_macro_node__upd_trig
AFTER UPDATE ON "macro_node"
FOR EACH ROW EXECUTE FUNCTION search_macro_node__upd_trig_fun();



INSERT INTO "search_macro_node" (id, "short_name", "full_name", "scenario_id")
SELECT
    "macro_node"."id" AS id,
    osrd_prepare_for_search(macro_node.short_name) AS short_name,
    osrd_prepare_for_search(macro_node.full_name) AS full_name,
    (macro_node.scenario_id) AS scenario_id
FROM "macro_node"
    ;
